const visitorForm = document.querySelector("#visitor-form");
const visitorUnit = document.querySelector("#visitor-unit");
const ownVisitorsList = document.querySelector("#own-visitors-list");

function escapeHtml(value) { return String(value ?? "").replace(/[&<>'"]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character]); }
function costaRicaDate(date = new Date()) { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Costa_Rica", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date); const value = Object.fromEntries(parts.map((part) => [part.type, part.value])); return `${value.year}-${value.month}-${value.day}`; }
function localDateTimeInput(date = new Date()) { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Costa_Rica", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(date); const value = Object.fromEntries(parts.map((part) => [part.type, part.value])); return `${value.year}-${value.month}-${value.day}T${value.hour}:${value.minute}`; }
function formatDateTime(value) { return new Intl.DateTimeFormat("es-CR", { timeZone: "America/Costa_Rica", dateStyle: "medium", timeStyle: "short" }).format(new Date(value)); }
function apiError(code) { return ({ invalid_visitor_authorization: "Revisa el nombre, tipo de visita y vivienda.", invalid_visit_time: "Selecciona una fecha y hora futura.", invalid_recurring_schedule: "Selecciona el periodo, la hora y al menos un día de la semana.", not_current_resident: "Solo puedes preautorizar visitas para tu residencia activa.", duplicate_visitor_authorization: "Esta visita ya está preautorizada para la vivienda y el mismo horario." })[code] || "No pudimos completar la acción."; }
async function api(path, options = {}) { const response = await fetch(path, { ...options, headers: { "Content-Type": "application/json", Accept: "application/json", ...options.headers } }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(apiError(payload.error)); return payload; }
const visitorTypes = { guest: "Invitado", delivery: "Entrega", domestic_worker: "Servicio doméstico", service: "Servicio técnico", contractor: "Contratista", transport: "Transporte", other: "Otro" };
const weekdayNames = ["domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado"];
function scheduleLabel(item) { if (item.schedule_type === "one_time") return formatDateTime(item.one_time_at); let days = []; try { days = JSON.parse(item.weekdays_json).map((day) => weekdayNames[day]); } catch { days = []; } return `${days.join(", ")} a las ${item.recurring_time} · desde ${item.recurring_start_date}${item.open_ended ? " · sin fecha final" : ` hasta ${item.recurring_end_date}`}`; }
async function loadMine() { const payload = await api("/api/visitors/mine"); visitorUnit.innerHTML = payload.units.length ? payload.units.map((unit) => `<option value="${escapeHtml(unit.id)}">Vivienda ${escapeHtml(unit.number)}</option>`).join("") : '<option value="">Sin residencia activa</option>'; visitorForm.querySelector("button[type=submit]").disabled = payload.units.length === 0; const today = costaRicaDate(); const active = payload.authorizations.filter((item) => item.active && (item.schedule_type === "one_time" ? new Date(item.one_time_at).getTime() >= Date.now() - 15 * 60000 : item.recurring_end_date >= today)); ownVisitorsList.innerHTML = active.length ? active.map((item) => `<article class="own-visitor-card"><div><span class="visitor-type">${escapeHtml(visitorTypes[item.visitor_type] || item.visitor_type)}</span><h4>${escapeHtml(item.visitor_name)}</h4><p>Vivienda ${escapeHtml(item.unit_number)} · ${escapeHtml(scheduleLabel(item))}</p><small>Registrado por ${escapeHtml(item.created_by_first_name)} ${escapeHtml(item.created_by_last_name)}</small>${item.notes ? `<small>${escapeHtml(item.notes)}</small>` : ""}</div><button type="button" class="danger-action" data-cancel-visitor="${escapeHtml(item.id)}">Cancelar</button></article>`).join("") : '<p class="empty-day">No hay preautorizaciones activas para tu vivienda.</p>'; }
function updateEndDate() { const openEnded = visitorForm.elements.openEnded.checked; visitorForm.elements.endDate.disabled = openEnded; visitorForm.elements.endDate.required = visitorForm.elements.scheduleType.value === "weekly" && !openEnded; document.querySelector("[data-end-date]").classList.toggle("disabled-field", openEnded); }
function updateScheduleFields() { const type = visitorForm.elements.scheduleType.value; visitorForm.querySelectorAll("[data-schedule]").forEach((element) => { element.hidden = element.dataset.schedule !== type; }); visitorForm.elements.oneTimeAt.required = type === "one_time"; visitorForm.elements.startDate.required = type === "weekly"; visitorForm.elements.recurringTime.required = type === "weekly"; updateEndDate(); }
function setDefaultDates() { const now = new Date(); const later = new Date(now.getTime() + 30 * 60000); const end = new Date(now); end.setMonth(end.getMonth() + 3); visitorForm.elements.oneTimeAt.value = localDateTimeInput(later); visitorForm.elements.startDate.value = costaRicaDate(); visitorForm.elements.endDate.value = costaRicaDate(end); visitorForm.elements.recurringTime.value = "08:00"; }
visitorForm.addEventListener("change", (event) => { if (["scheduleType", "openEnded"].includes(event.target.name)) updateScheduleFields(); });
visitorForm.addEventListener("submit", async (event) => { event.preventDefault(); const feedback = document.querySelector("#visitor-feedback"); const form = new FormData(visitorForm); feedback.textContent = "Guardando…"; try { await api("/api/visitors", { method: "POST", body: JSON.stringify({ unitId: form.get("unitId"), visitorName: form.get("visitorName"), visitorType: form.get("visitorType"), scheduleType: form.get("scheduleType"), oneTimeAt: form.get("oneTimeAt"), startDate: form.get("startDate"), endDate: form.get("endDate"), openEnded: form.get("openEnded") === "on", recurringTime: form.get("recurringTime"), weekdays: form.getAll("weekdays").map(Number), vehiclePlate: form.get("vehiclePlate"), notes: form.get("notes") }) }); visitorForm.reset(); setDefaultDates(); updateScheduleFields(); feedback.textContent = "Preautorización guardada."; await loadMine(); } catch (error) { feedback.textContent = error.message; } });
ownVisitorsList.addEventListener("click", async (event) => { const button = event.target.closest("[data-cancel-visitor]"); if (!button) return; button.disabled = true; try { await api(`/api/visitors/${button.dataset.cancelVisitor}/cancel`, { method: "PATCH" }); await loadMine(); } catch (error) { button.disabled = false; window.alert(error.message); } });
document.addEventListener("naia:authorization", async (event) => { if (!event.detail.profile?.permissions.includes("visitors.create")) return; setDefaultDates(); updateScheduleFields(); await loadMine(); });
